# ----------------------- options / filenames / feedback ---------------------
#
def check_options(comargs):
    """Check options and make consistent

    Some values inserted into comargs structure
    """
    # Input filenames
    if not comargs.fq1:
        print("Problem: Need to specify inputs; Try --help or --explain")
        return False

    # Group spec given or from file
    if comargs.gfile:
        if not check_infile(comargs.gfile, verb=True):
            print(f"Problem with group specification list {comargs.gfile}")
            return False
    if (not comargs.gfile) and (not comargs.group):
        print("Problem: Need to specify groups")
        return False

    # Given chem and kit must be legit
    if not comargs.chemistry:
        print("Problem: Need to specify chemistry")
        return False
    chem = parse_chemistry(comargs.chemistry)
    if not chem:
        print(f"Problem with given chemistry '{comargs.chemistry}'")
        return False
    comargs.chemistry = chem

    if not comargs.kit:
        print("Problem: Need to specify kit")
        return False
    kit_s, _ = parse_kit(comargs.kit)
    if not kit_s:
        print(f"Problem with given kit '{comargs.kit}'")
        report_valid_kits()
        return False
    comargs.kit = kit_s

    # Fastq bc sample slice
    if not comargs.bc_samp_slice:
        comargs.bc_samp_slice = DEF_BC_SAMP_SLICE
    # Range of records to process
    ok, first, last = parse_range_list(comargs.bc_samp_slice)
    if not ok:
        print(f"Bad bc_samp_slice given; {comargs.bc_samp_slice}")
        return False
    comargs.bc_samp_first = first
    comargs.bc_samp_last = last

    # Max edit dist
    if comargs.edit_dist < 0:
        comargs.edit_dist = DEF_BC_EDIT_DIST
    comargs.edit_dist = int(comargs.edit_dist)

    # Ouptut dir and filename prefix
    if not comargs.output_dir:
        fq1_list = check_infile(comargs.fq1)
        output_dir = get_output_dir_from_fq1(fq1_list[0])
        if comargs.path_prefix:
            prefix = comargs.path_prefix
            if prefix[-1] != "/":
                prefix += "/"
            output_dir = prefix + output_dir
        comargs.output_dir = output_dir

    if not comargs.opref:
        comargs.opref = DEF_OPREF

    # Range of records to process
    ok, first, last = parse_range_list(comargs.range)
    if not ok:
        print(f"Bad range given; {comargs.range}")
        return False
    comargs.rec_first = first
    comargs.rec_last = last

    # Fastq header name checks
    if comargs.no_name_check:
        comargs.name_check = False
    else:
        comargs.name_check = True
    # Separator for <name> <num> in header for name checking
    if comargs.slash_name_sep:
        comargs.name_num_sep = "/"
    else:
        comargs.name_num_sep = " "

    # Background gz compressor; Use by default
    if comargs.write_gz or comargs.no_back_gz:
        comargs.back_gz = False
    else:
        comargs.back_gz = True
        # Output dir has to be clean; Can't exist
        if os.path.exists(comargs.output_dir):
            print("# For background gz compression, output_dir cannot exist")
            if comargs.force:
                print(f"# REMOVING '{comargs.output_dir}'")
                shutil.rmtree(comargs.output_dir)
            else:
                print(f"Remove '{comargs.output_dir}' and try again")
                return False

    return True


def set_chem_kit_pars(comargs):
    """Set chemistry and kit specific things

    Retuern status
    """
    amp_seq = get_amp_seq(comargs.chemistry)
    if not amp_seq:
        print("No amplicon seq found")
        return False
    comargs.amp_seq = amp_seq

    n_bc_rounds = kit_chem_bc_rounds(comargs.kit, comargs.chemistry)
    if not n_bc_rounds:
        print("No kit bc_rounds number found")
        return False
    comargs.n_bc_rounds = n_bc_rounds

    return True


def get_amp_seq(chem):
    """Get chem-specific amplicon seq

    Return str
    """
    # Read structure
    chem_n = parse_chemistry(chem)
    if (chem_n == 3) or (chem_n == 4):
        seq = "NNNNNNNNNN33333333ATGAGGGGTCAG22222222TCCAACCACCTC11111111"
    elif chem_n == 2:
        seq = "NNNNNNNNNN33333333GTGGCCGATGTTTCGCATCGGCGTACGACT22222222ATCCACGTGCTTGAGACTGTGG11111111"
    else:
        print(f"Bad chemistry {chem}; No amplicon seq")
        seq = ""

    return seq


def get_fq2_from_fq1(fq1):
    """Try to get fq2 (R2) name from fq1 (R1) filename"""
    print("# Using R1 to get R2 fastq")
    fq2 = ""
    parts = fq1.split("R1")
    # Make sure 'R1' is in name and only sub last instance
    #   e.g. '/pathR1/examR1.fq' >--> '/pathR1/examR2.fq'
    if len(parts) > 1:
        fq2 = "R1".join(parts[:-1]) + "R2" + parts[-1]
    return fq2


def get_output_dir_from_fq1(fq1):
    """Try to get output_dir name from fq1"""
    print("# Using fastq R1 name to get output_dir")
    output_dir = ""
    parts = fq1.split("R1")
    # Make sure 'R1' is in name and only sub last instance
    #   e.g. '/pathR1/examR1.fq' >--> 'exam/'
    if len(parts) > 1:
        output_dir = "R1".join(parts[:-1])
        # Remove any trailing underscore, strip any preceeding path, add slash
        output_dir = output_dir.rstrip("_")
        output_dir = output_dir.split("/")[-1]
        output_dir += "/"
    return output_dir


def set_up_full_fnames(comargs):
    """Set up input and output filename stuff"""
    # Input fastq pair(s)
    fq1_list = check_infile(comargs.fq1)
    if not fq1_list:
        return False
    # Get given fq2 list or derive from fq1
    if comargs.fq2:
        fq2_list = check_infile(comargs.fq2)
        if not fq2_list:
            return False
    else:
        fq2_list = []
        for fq1 in fq1_list:
            fname = get_fq2_from_fq1(fq1)
            fq2_list.append(fname)
    if len(fq1_list) != len(fq2_list):
        print(f"Number of fq1 ({len(fq1_list)}) differs from fq2 ({len(fq2_list)}")
        return False
    comargs.fq1_list = fq1_list
    comargs.fq2_list = fq2_list

    # Output path. Only try to create if doesn't exist
    if not os.path.isdir(comargs.output_dir):
        try:
            os.makedirs(comargs.output_dir)
        except Exception as e:
            print(f"Problem creating subdir {comargs.output_dir}", e)
            return False

    comargs.output_dir = check_infile(comargs.output_dir, verb=True)
    return True


def get_fastq_guess(comargs, f_ind=0):
    """Get guess of number of records in fastq pair for given index"""
    fq1_name = comargs.fq1_list[f_ind]
    fq2_name = comargs.fq2_list[f_ind]
    # Guess returns number and story. Only want average number guess
    g1, _ = guess_fastq_gz_read_count(fq1_name)
    g2, _ = guess_fastq_gz_read_count(fq2_name)
    return int((g1 + g2) / 2)


