def report_in_fastq_str(comargs, which):
    """Story part for fastq file(s)

    Return string
    """
    if which == 1:
        which_str = "R1"
        f_list = comargs.fq1_list
    elif which == 2:
        which_str = "R2"
        f_list = comargs.fq2_list
    else:
        raise ValueError(f"Bad {which=} arg given")

    if len(f_list) > 1:
        part_list = [f"# Fasta {which_str} file list, {len(f_list)} files"]
        for fname in f_list:
            part_list.append(f"#               {fname}")
        story = "\n".join(part_list)
    else:
        story = f"# Fasta {which_str}      {f_list[0]}"

    return story


# -------------------------- Background gz compression ------------------------
#
def check_pigz_compressor(comargs):
    """Check if pigz is installed, warn if needed"""
    if comargs.back_gz:
        print("#")
        try:
            result = subprocess.run(
                ["pigz", "-V"],
                capture_output=True,
                text=True,
                check=True,
            )
            ver = result.stdout.strip()
            story = f"# Found {ver} and will use for parallel gzip compression"
        except Exception:
            story = "!\n"
            story += "!                >>>  WARNING  <<<\n"
            story += "! Did not find 'pigz' so no parallel gzip compression\n"
            story += "! Fallback to 'gzip' may be significantly slower ...\n"
            story += "! You might want to install 'pigz' before proceeding\n"
            story += "!"
        print(story)


def back_gz_sent_filename(comargs):
    """Get sentinel file path for background gz process termination"""
    sent_file = f"{comargs.output_dir}{BACK_GZ_SENT_FILE}"
    return sent_file


def gz_compressor(dirpath, sentinel, poll_interval=0.5, verb=False):
    """per ChatGPT:
    Polls `dirpath` for new *.fq files.
    For each one not yet processed:
      • runs pigz -f -p<N> file.fq  (or gzip -f fallback)
      • deletes the raw file.fq
    Exits once the sentinel exists and no .fq remain.
    """
    processed = set()
    cores = os.cpu_count() or 1

    while True:
        for fn in os.listdir(dirpath):
            if not fn.endswith(BACK_GZ_PRE_EXT) or fn in processed:
                continue

            path = os.path.join(dirpath, fn)
            # compress in-place
            try:
                subprocess.run(["pigz", "-f", "-p", str(cores), path], check=True)
            except FileNotFoundError:
                subprocess.run(["gzip", "-f", path], check=True)

            processed.add(fn)
            if verb:
                print(f"# [compressor] compressed {fn} >--> {fn}.gz")

        # exit condition: sentinel + no .fq left to process
        if os.path.exists(sentinel):
            # check if any unprocessed .fq remain
            remaining = [
                fn for fn in os.listdir(dirpath) if fn.endswith(BACK_GZ_PRE_EXT)
            ]
            if not remaining:
                break

        time.sleep(poll_interval)


def lanuch_gz_compressor(comargs, oset_dict):
    """Possibly launch background gz compression processes

    Return Process
    """
    if not comargs.back_gz:
        return None

    # Create, start, return
    sent_file = back_gz_sent_filename(comargs)
    comp = Process(target=gz_compressor, args=(comargs.output_dir, sent_file))
    comp.start()
    return comp


def finish_back_gz(comargs, bz_proc, oset_dict):
    """Finish background gz compression stuff"""
    sent_file = back_gz_sent_filename(comargs)
    open(sent_file, "w").close()
    print("# Waiting for backround gz compressor to finish ...")
    bz_proc.join()

    print("# Compressors all done; Merging output blocks")
    for name, oset in oset_dict.items():
        f1_list = oset.get_block_file_list(1)
        f2_list = oset.get_block_file_list(2)
        fname1 = oset.get_fname(1, as_block=False, as_gz=True)
        fname2 = oset.get_fname(2, as_block=False, as_gz=True)
        if not f1_list:
            print(f"# {name} has NO outputs")
            continue

        ok1, story = gz_blocks_to_new(f1_list, fname1)
        if not ok1:
            print("PROBLEM with {name} R1; {story}")
        ok2, story = gz_blocks_to_new(f2_list, fname2)
        if not ok2:
            print("PROBLEM with {name} R2; {story}")
        if ok1 and ok2:
            count = oset.get_count()
            print(f"# {name}\t{count:,} records;\t{fname1} (and R2)")


def gz_blocks_to_new(p_list, new_file):
    """Concatenate or rename list of block files to new file

    Return status, str
    """
    if not p_list:
        return True, ""

    ok = True
    story = new_file
    # Simple rename single file
    if len(p_list) == 1:
        try:
            os.rename(p_list[0], new_file)
        except Exception as e:
            ok = False
            story = e
    # Concat multiple files, then remove parts
    else:
        cmd = ["cat"] + p_list
        with open(new_file, "wb") as out_f:
            try:
                subprocess.run(cmd, stdout=out_f, check=True)
            except subprocess.CalledProcessError as e:
                ok = False
                story = e
        if ok:
            for p in p_list:
                os.remove(p)

    return ok, story


# ----------------------------- Group (well) specs ----------------------------
# Groups of wells for output
#
# Class to hold info on output groups of wells
class Outset(object):
    def __init__(self, name, sdef, opath, opref="", write_gz=False, write_blocks=False):
        """
        name = group name
        sdef = well specification string
        opath = output_dir
        opref = prefix for group name output files
        write_gz = flag to write gz output directly (gzip.write)
        write_blocks = flag to output per-write-block temp files (for background gz compression)
        """
        self.name = name
        self.sdef = sdef
        self.count = 0
        self.block = 0
        self._set_fnames(opath, opref)
        self.write_gz = write_gz
        self.write_blocks = write_blocks
        # Set of wells to match
        # Returns status, list of per-bc-round well lists, canonical spec, issue story
        ok, pw_list, _, story = parse_mround_plate96_wells(sdef)
        assert ok, story
        self.well_list = pw_list
        self._make_well_set()
        # Output files and buffers
        self.fq1 = None
        self.fq2 = None
        self._r1_blines = []
        self._r2_blines = []
        self._init_buffers()

    def __del__(self):
        self.write_out_bufs()
        self.close_ofiles()

    def __repr__(self):
        ostring = "Outset (output set definition)\n"
        ostring += f"Name:      {self.get_name()}\n"
        ostring += f"SampDef:   {self.sdef}\n"
        ostring += f"BC_rounds: {self.num_bc_rounds()}\n"
        well_list = self.get_well_list()
        ostring += f"Well_sets: {well_list}\n"
        ostring += f"Files:     {self.get_fname(1)}   {self.get_fname(2)}\n"
        return ostring

    def _make_well_set(self):
        """Make working set of wells or r1-r2 well combos"""
        if len(self.well_list) > 1:
            well_list = []
            for combo in [(x, y) for x in self.well_list[0] for y in self.well_list[1]]:
                well_list.append(combo)
        else:
            well_list = self.well_list[0]
        self.well_set = set(well_list)

    def _set_fnames(self, opath, opref=""):
        """Set output path and base case fastq filenames
        opath = output_dir path
        opref = output filename prefex (before group name)
        """
        if not opath.endswith("/"):
            opath = opath + "/"
        name = self.name
        if opref:
            name = f"{opref}_{name}"
        self.opath = opath
        # Fastq names without gz
        self.fq1_fname = f"{opath}{name}_R1.fastq"
        self.fq2_fname = f"{opath}{name}_R2.fastq"

    def _init_buffers(self):
        self.r1_blines = []
        self.r2_blines = []
        self.n_buf = 0

    def is_write_gz(self):
        return self.write_gz

    def is_write_blocks(self):
        return self.write_blocks

    def get_fname(
        self, which, ext=BACK_GZ_TMP_EXT, as_gz=False, as_block=True, block=None
    ):
        """Return one or more output filenames
        which = 1 or 2
        ext = extension (if writing blocks)
        as_gz = flag to get gzip'd .gz version
        as_block = flag to rename for block-based writing
        """
        fname = ""
        if which == 1:
            fname = self.fq1_fname
        elif which == 2:
            fname = self.fq2_fname
        else:
            raise ValueError(f"Bad {which=} arg given")
        # Add gz extension or make block name
        if self.is_write_gz() or as_gz:
            fname = f"{fname}.gz"
        elif self.is_write_blocks() and as_block:
            if block is None:
                block = self.block
            # Replacement string: e.g. 'ABC_R1.fastq' >--> 'ABC_R1_blk0001.tmp'
            rep_string = f"_blk{block:04d}.{ext}"
            fname = fname[: -len(".fastq")] + rep_string

        # print(f"<< get_fname {fname=}")
        return fname

    def get_ofiles(self):
        """Get output files for this sample
        block = output block number (if any)
        block_ext = block output file extension; Write to temp before compression
        """
        if self.fq1 is None:
            fq1_name = self.get_fname(1)
            fq2_name = self.get_fname(2)
            if self.is_write_gz():
                self.fq1 = gzip.open(fq1_name, "wb", compresslevel=GZIP_COMPRESSLEVEL)
                self.fq2 = gzip.open(fq2_name, "wb", compresslevel=GZIP_COMPRESSLEVEL)
            else:
                self.fq1 = open(fq1_name, "w")
                self.fq2 = open(fq2_name, "w")
        return self.fq1, self.fq2

    def close_ofiles(self, verb=True):
        """Close files if open"""
        if self.fq1:
            if verb:
                n = self.get_count()
                fname = self.get_fname(1)
                print(f"New files: {fname}  (and R2)  {n:,}")
            self.fq1.close()
            self.fq2.close()
            self.fq1 = self.fq2 = None

    def write_rec(self, head1, seq1, plus1, qual1, head2, seq2, plus2, qual2):
        """Handle writing for two fastq records; Four lines each R1 R2"""
        self.r1_blines += [head1 + seq1 + plus1 + qual1]
        self.r2_blines += [head2 + seq2 + plus2 + qual2]
        self.inc_count()
        self.n_buf += 1
        if self.n_buf >= OUT_REC_BUFFER:
            self.write_out_bufs()
        return True

    def write_out_bufs(self):
        """Write any bufferd lines to file"""
        if self.n_buf:
            r1_buf = "".join(self.r1_blines)
            r2_buf = "".join(self.r2_blines)
            ofile1, ofile2 = self.get_ofiles()
            if self.is_write_gz():
                ofile1.write(r1_buf.encode("ascii"))
                ofile2.write(r2_buf.encode("ascii"))
            else:
                ofile1.write(r1_buf)
                ofile2.write(r2_buf)
            ofile1.flush()
            ofile2.flush()
            # Per block writing closes after each block and rename
            if self.is_write_blocks():
                self.close_ofiles(verb=False)
                self.rename_temp_files()
            # Update block count and reset output buffers
            self.block += 1
            self._init_buffers()

    def rename_temp_files(self):
        """Rename temp block files to pre-compression files"""
        fq1_tmp = self.get_fname(1, ext=BACK_GZ_TMP_EXT, as_block=True)
        fq2_tmp = self.get_fname(2, ext=BACK_GZ_TMP_EXT, as_block=True)
        fq1_pre = self.get_fname(1, ext=BACK_GZ_PRE_EXT, as_block=True)
        fq2_pre = self.get_fname(2, ext=BACK_GZ_PRE_EXT, as_block=True)
        os.rename(fq1_tmp, fq1_pre)
        os.rename(fq2_tmp, fq2_pre)
        # print(f"Renamed {fq1_tmp} {fq1_pre}")
        # print(f"Renamed {fq2_tmp} {fq2_pre}")

    def get_block_file_list(self, which, ext=BACK_GZ_DONE_EXT):
        """Get list of block files"""
        flist = []
        for i in range(self.get_block()):
            flist.append(self.get_fname(which, ext=ext, as_block=True, block=i))
        return flist

    def inc_count(self, inc=1):
        self.count += inc

    def get_count(self):
        return self.count

    def get_block(self):
        return self.block

    def get_well_list(self, which=0):
        if which == 0:
            answer = self.well_list
        elif which == 1:
            answer = self.well_list[0]
        elif which == 2:
            answer = self.well_list[1]
        return answer

    def get_well_set(self):
        return self.well_set

    def num_bc_rounds(self):
        return len(self.get_well_set())

    def get_name(self):
        return self.name

    def get_sampdef(self, out_set=True):
        ostr = self.sdef
        if out_set:
            wset_list = self.get_well_list()
            if len(wset_list) == 1:
                wset_list = sort_wells(wset_list[0])
            ostr += f"\t{wset_list}"
        return ostr

    def get_report(self):
        ostring = f"{self.get_name()}\t{self.get_sampdef()}"
        return ostring


def get_outsets(comargs, bc_info):
    """Get output well/cell subset collection

    Return dict of Outset objects
    """
    # Collect subset defs; Sample wells or cells
    def_list = []
    # Samples will only look at first (one) barcode
    if comargs.gfile:
        def_list = load_def_list(comargs.gfile)
    elif comargs.group:
        for samp_def in comargs.group:
            if len(samp_def) < 2:
                print(f"Problem parsing '{samp_def}' as groups (wells)")
                def_list = []
                break
            def_list.append(samp_def[:2])

    # Should have something
    if not def_list:
        return None

    # print("DDD", def_list)

    # List of plate-rows per barcode based on kit
    kit = comargs.kit
    pdim_list = kit_chem_plate_dims(kit)

    # Collect objects for all names and well specs
    out_dict = {}
    for name, s_def in def_list:
        if name in out_dict:
            print(f"Problem with groups; Name '{name}' is not unique")
            return None

        # Returns status, list of per-bc-round well lists, canonical spec, issue story
        ok, pw_list, _, story = parse_mround_plate96_wells(s_def)
        if not ok:
            print(f"Problem parsing {name} '{s_def}' as groups (wells)")
            print(story)
            return None

        # Make sure wells 'fit' kit plates
        if len(pw_list) != len(pdim_list):
            print(f"Problem parsing {name} '{s_def}' as groups (wells)")
            print(f"BC rounds for for kit {kit} = {len(pdim_list)} -vs- {len(pw_list)}")
            return None
        bc_round = 0
        for well_list, p_rows in zip(pw_list, pdim_list):
            bc_round += 1
            plate_set = set(wells_for_96plate(p_rows))
            well_set = set(well_list)
            bad_set = well_set - plate_set
            if bad_set:
                print(f"Problem parsing {name} '{s_def}' as groups (wells)")
                print(f"Wells for kit {kit} are out of bounds (bc round {bc_round}):")
                print(bad_set)
                return None

        # If background gz compression, write blocks
        out_dict[name] = Outset(
            name,
            s_def,
            comargs.output_dir,
            opref=comargs.opref,
            write_gz=comargs.write_gz,
            write_blocks=comargs.back_gz,
        )

    return out_dict


def load_def_list(fname):
    def_list = []
    with open(fname) as INFILE:
        for line in INFILE:
            # Ignore '#' commented out / blank lines
            parts = line.strip().split("#")[0].split()
            # Def should have <name> <wells/cells>
            if len(parts) >= 2:
                def_list.append(parts[:2])
    return def_list


def check_outset_overlap(oset_dict):
    """Check for any pairwise overlap among defined groups"""
    key_list = list(oset_dict.keys())
    for i in range(len(key_list) - 1):
        for j in range(i + 1, len(key_list)):
            oset1 = oset_dict[key_list[i]]
            oset2 = oset_dict[key_list[j]]
            wells1 = oset1.get_well_set()
            wells2 = oset2.get_well_set()
            over_set = wells1 & wells2
            if over_set:
                print("Problem. Overlapping group wells not allowed")
                print(
                    f"Groups '{oset1.get_name()}' and '{oset2.get_name()}' overlap: {over_set}"
                )
                return False
    return True


def invert_redun_dict(in_dict):
    """Invert redundant-value dict so new new values = list of orig keys"""
    new_dict = defaultdict(list)
    for k, v in in_dict.items():
        new_dict[v].append(k)
    return new_dict


def wells_to_seq_list(wells, w2s_dict):
    """Get list of seqs for correspondng wells from given redundant dict

    Return list
    """
    seqs = []
    for w in wells:
        seqs += w2s_dict[w]
    return seqs


def bc_out_seq_dict(oset_dict, bc_info, n_bc_rounds):
    """Get dict of Bcout objs indexed by barcode sequence(s)

    Return dict
    """
    # Dict of lists as one seq can have multiple output groups
    seq_oset_dict = {}

    # Two round sample defs use (bc1-seq, bc2-seq) tuples as keys
    if n_bc_rounds == 2:
        well_to_seq1 = invert_redun_dict(bc_info["bc_seq_to_well"][1])
        well_to_seq2 = invert_redun_dict(bc_info["bc_seq_to_well"][2])
        for oset in oset_dict.values():
            seq_list1 = wells_to_seq_list(oset.get_well_list(1), well_to_seq1)
            seq_list2 = wells_to_seq_list(oset.get_well_list(2), well_to_seq2)
            # Keys = pairwise combos
            for combo in [(x, y) for x in seq_list1 for y in seq_list2]:
                seq_oset_dict[combo] = oset

    # Single round sample defs use bc sequence as keys
    else:
        well_to_seq = invert_redun_dict(bc_info["bc_seq_to_well"][1])
        for oset in oset_dict.values():
            seq_list = wells_to_seq_list(oset.get_well_set(), well_to_seq)
            for seq in seq_list:
                # seq_oset_dict[seq].append(oset)
                seq_oset_dict[seq] = oset

    return seq_oset_dict


# ------------------------- Main loop over inputs ----------------------------
#
def proc_fastq_loop(comargs, f_ind, bc_info, seq_oset_dict, rec_guess=0):
    """Process loop for one pair of fastq files

    f_ind = 0-based fastq pair index
    bc_info = barcode info stuff
    seq_oset_dict = dict[seq(s)] = Outset obj

    Return dict
    """
    # Get various working vars. As locals speeds up a little
    # Add 1 to len as checked with newline (no strip)
    s2_min_len = len(bc_info["amp_seq"]) + 1
    bc1_start = bc_info["bc_starts"][1]
    bc2_start = bc_info["bc_starts"][2]
    bc3_start = bc_info["bc_starts"][3]
    bc1_end = bc_info["bc_ends"][1]
    bc2_end = bc_info["bc_ends"][2]
    bc3_end = bc_info["bc_ends"][3]

    bc_dicts = bc_info["bc_dicts"]
    counts = bc_info["bc_counts"]
    ct_thresh = bc_info["bc_count_thresh"]

    max_edist = comargs.edit_dist
    two_rounds = True if (comargs.n_bc_rounds == 2) else False
    rec_first = comargs.rec_first
    rec_last = comargs.rec_last
    name_check = comargs.name_check
    name_num_sep = comargs.name_num_sep

    if rec_guess and rec_last:
        rec_guess = min(rec_guess, rec_last)

    fq1_name = comargs.fq1_list[f_ind]
    fq2_name = comargs.fq2_list[f_ind]

    n_rec = n_check = n_short = n_valid = n_out = 0
    bc_edit_dist_NA = bc_edit_dist_0 = bc_edit_dist_1 = bc_edit_dist_2 = 0

    with gzip.open(fq1_name, "rt") as fq1_file, gzip.open(fq2_name, "rt") as fq2_file:

        # Run through fastq records
        end_str = f"  Max records {rec_last:,}" if rec_last else ""
        print_now(f"# Processing reads...{end_str}")

        while True:
            # Each file, header, seq, strand, and quality lines
            head1 = fq1_file.readline()
            seql1 = fq1_file.readline()
            plus1 = fq1_file.readline()
            qual1 = fq1_file.readline()

            head2 = fq2_file.readline()
            seql2 = fq2_file.readline()
            plus2 = fq2_file.readline()
            qual2 = fq2_file.readline()

            # All done?
            if (not seql1) or (not seql2):
                break

            n_rec += 1
            # Before or after range?
            if n_rec < rec_first:
                continue
            if rec_last and (n_rec > rec_last):
                break

            if (n_rec % UPDATE_FREQ) == 0:
                if rec_guess:
                    percent = round(100 * n_rec / rec_guess, 2)
                    per_str = f" ... ({percent} % done)"
                else:
                    per_str = ""
                print_now(f"# record {n_rec:,}{per_str}")
            n_check += 1

            # Checking name match?
            if name_check:
                head_is_good = True
                name1 = name2 = read1 = read2 = ""
                try:
                    ind = head1.find(name_num_sep)
                    name1 = head1[:ind]
                    read1 = head1[ind + 1]
                    ind = head2.find(name_num_sep)
                    name2 = head2[:ind]
                    read2 = head2[ind + 1]
                except Exception:
                    head_is_good = False

                if head_is_good:
                    if (name1 != name2) or (read1 != "1") or (read2 != "2"):
                        head_is_good = False

                if not head_is_good:
                    print(f"Fastq R1 R2 header mismatch at record {n_rec}")
                    print(f"Fastq files: |{fq1_name}|  |{fq2_name}|")
                    print(f"Header fq1: {head1}")
                    print(f"Header fq2: {head2}")
                    print(f"Names |{name1}| |{name2}|")
                    print(f"Reads |{read1}| |{read2}|")
                    break

            # Too short for barcodes
            if len(seql2) < s2_min_len:
                n_short += 1
                continue

            """
            # Extract bc 1 and maybe 2. Set key for perfect-match case
            rbc1 = key = seql2[bc1_start:bc1_end]
            if two_rounds:
                rbc2 = seql2[bc2_start:bc2_end]
                key = (rbc1, rbc2)
                """

            # Raw barcodes
            rbc1 = seql2[bc1_start:bc1_end]
            rbc2 = seql2[bc2_start:bc2_end]
            rbc3 = seql2[bc3_start:bc3_end]

            # print(f"XXX {n_rec=} {rbc1} {rbc2} {rbc3}")

            # Returns three bc seq strings, or empty strings if no match
            # Also returns maximum edit distance and sum of these
            bc1, bc2, bc3, ed_max, ed_sum = correct_barcodes(
                rbc1, rbc2, rbc3, counts, ct_thresh, bc_dicts, max_edist
            )
            # Edit dist stats
            if ed_max == 0:
                bc_edit_dist_0 += 1
            elif ed_max == 1:
                bc_edit_dist_1 += 1
            elif ed_max == 2:
                bc_edit_dist_2 += 1
            else:
                bc_edit_dist_NA += 1

            # Only process if all 3 barcodes, even though sample specified by fewer
            if bc1 and bc2 and bc3:
                n_valid += 1
                if two_rounds:
                    bc_key = (bc1, bc2)
                else:
                    bc_key = bc1

                if bc_key in seq_oset_dict:
                    oset = seq_oset_dict[bc_key]

                    # print(f"WWW {n_rec=} {oset.get_name()} {bc_key=}")

                    if not oset.write_rec(
                        head1, seql1, plus1, qual1, head2, seql2, plus2, qual2
                    ):
                        print(f"Problem writing output for {oset.get_name()}; Bailing")
                        print(f"Number reads so far {n_rec}")
                        print(oset)
                        return None

                    n_out += 1
                    continue

    read_stats = {
        "num_rec": n_rec,
        "num_check": n_check,
        "num_short": n_short,
        "num_valid": n_valid,
        "num_out": n_out,
        "bc_edit_dist_0": bc_edit_dist_0,
        "bc_edit_dist_1": bc_edit_dist_1,
        "bc_edit_dist_2": bc_edit_dist_2,
        "bc_edit_dist_NA": bc_edit_dist_NA,
    }

    return read_stats


