def _make_kit_chem_dtab_df():
    """Get kit / chemistry defs table as dataframe"""
    head_row = []
    rows = []
    for line in KIT_CHEM_DEFS.split("\n"):
        parts = line.split("#")[0].split()
        if parts:
            if head_row:
                rows.append(parts)
            else:
                head_row = parts
    kit_df = pd.DataFrame(rows, columns=head_row)

    kit_df["chem"] = kit_df["chem"].astype(int)
    # Make sure all "int alias" values are int
    kit_df["ialias"] = (
        pd.to_numeric(kit_df["ialias"], errors="coerce").fillna(0).astype(int)
    )

    # Add extra stuff; bc_rounds, rows, wells
    # Split sample plate dims list on comma, cast list values to int
    kit_df["sp_dims"] = kit_df["sp_dims"].apply(
        lambda lst: [int(r) for r in lst.split(",")]
    )
    # Number of rounds for sample specs = number of values for sample plate dims
    kit_df["bc_rounds"] = kit_df["sp_dims"].apply(len)
    kit_df["n_wells"] = kit_df["sp_dims"].apply(sum) * 12

    return kit_df


# Create once as global
KIT_CHEM_DTAB = _make_kit_chem_dtab_df()


def get_all_chem_list(as_str=False):
    """List of all valid chemistry values

    Default is int
    """
    # Want simple int
    chem_list = sorted([int(i) for i in KIT_CHEM_DTAB["chem"].unique()])
    if as_str:
        chem_list = [f"v{c}" for c in chem_list]

    return chem_list


def parse_chemistry(chem, as_str=False):
    """Parse given chemistry to standard form

    as_str = flag to return as str -vs- int

    Return str or int
    """
    # Valid number in list of legit numbers
    ok, n = str_to_num(chem, regex=True)
    if ok and (n in get_all_chem_list(as_str=False)):
        answer = n
    else:
        answer = 0

    # Return as string?
    if as_str:
        if answer == 0:
            answer = ""
        else:
            answer = f"v{answer}"
    return answer


def parse_kit(kit, chem=None, unique=True):
    """Attempt to parse given kit into canonical form

    unique = flag to fail if name without chem is ambiguous

    Returns canonical named kit and story if any issue

    Return (str, str)
    """
    if not kit:
        return "", "<empty kit>"

    # Make sure kit is string (e.g. in case given int)
    kit_s = str(kit)
    # If given chemistry, make sure it's good
    if chem:
        chem_s = parse_chemistry(chem)
        if not chem_s:
            return "", f"Bad chemistry ({chem}) given for parse_kit({kit})"
        chem = chem_s

    # If no chemistry, unique kit-chem not required
    if not chem:
        unique = False

    story = ""
    k_list = []
    df = KIT_CHEM_DTAB

    # Try to parse number first; If not int, empty list
    k_list = kit_chem_from_int(kit_s, chem=chem)
    if not k_list:
        # Lowercase and maybe dash not underscore (e.g. WT-mega >--> wt_mega)
        kit_s = kit_s.replace("-", "_").lower()
        df = df[df["kit"].str.lower() == kit_s]
        if chem:
            df = df[df["chem"] == chem]
        k_list = [list(t) for t in df[["kit", "chem"]].values]

    # Different story for different number of matches
    if len(k_list) < 1:
        kit_s = ""
        chem_story = f" (Chemistry {chem})" if chem else ""
        story = f"Kit '{kit}' unrecognized{chem_story}"
    elif len(k_list) > 1:
        if unique:
            kit_s = ""
            story = f"Kit '{kit}' ambiguous; [kit,chem] = {k_list}"
        else:
            # First one, as all in list match except for chem
            kit_s, chem = k_list[0]
    else:
        kit_s, chem = k_list[0]

    return kit_s, story


def kit_chem_from_int(kint, chem=None):
    """Get kit string from int alias, maybe qualified by chemistry

    kint = kit integer alias
    chem = chemistry

    Return list of lists [[kit,chem], [kit,chem], ...]
    """
    # If given number, make sure int; No regex, only simple int should work
    ok, kint = str_to_num(kint, regex=False)
    # No number or bogus number
    if (not ok) or (kint <= 0):
        return []

    # If given chemistry, get number for table
    if chem:
        chem = parse_chemistry(chem)
        if not chem:
            return []

    k_list = []
    df = KIT_CHEM_DTAB[KIT_CHEM_DTAB["ialias"] == kint]
    if len(df):
        # Apply any chem constraint
        if chem:
            df = df[df["chem"] == chem]
        k_list = [list(t) for t in df[["kit", "chem"]].values]

    return k_list


def kit_chem_dtab_subset(kit=None, chem=None, all_ktype=False):
    """Get subset of data table given various constraints

    kit = filter if given
    chem = filter if given
    all_ktype = flag to allow all kits; No filter for kit type="norm"

    Return dataframe
    """
    df = KIT_CHEM_DTAB

    if kit:
        # Kit and chem into canonical form
        kit, _ = parse_kit(kit, chem=chem)
        if not kit:
            return None
        df = df[df["kit"] == kit]

    # If chemistry, make sure canonical name (number) then filter
    # (zero is not a valid chemistry number; So no filtering if 0)
    if chem:
        chem = parse_chemistry(chem)
        if not chem:
            return None
        df = df[df["chem"] == chem]

    # Filter on any kit type constraint
    if not all_ktype:
        df = df[df["ktype"].str.startswith("norm")]

    return df


def kit_chem_list(kit=None, chem=None, all_ktype=False, chem_as_str=False):
    """Get list of valid [kit, chem] combos

    kit = filter if given
    chem = filter if given
    all_ktype = flag to allow all kits; No filter for kit type="norm"
    chem_as_str = flag to have chemistry as str (like "v3", vs 3)

    Return list of [[kit, chem],]
    """
    df = kit_chem_dtab_subset(kit=kit, chem=chem, all_ktype=all_ktype)
    if df is None:
        return []

    kc_list = []
    for k, c in zip(df["kit"], df["chem"]):
        if chem_as_str:
            c = f"v{c}"
        kc_list.append([k, c])

    return kc_list


def kit_chem_bc_rounds(kit, chem, all_ktype=True):
    """Get number of sample-specifiying bc_rounds for kit and chem

    all_ktype = flag to return all; No filter for kit type="norm"

    Return int
    """
    # Make sure valid kit
    kit, _ = parse_kit(kit, chem=chem)
    if not kit:
        return []
    # Legit kit and chem combo should yield single data row
    df = kit_chem_dtab_subset(kit, chem, all_ktype=all_ktype)
    if (df is None) or (len(df) != 1):
        return 0

    num = int(df["bc_rounds"].iloc[0])
    return num


def kit_chem_plate_dims(kit, chem=0, into="", all_ktype=True):
    """Get plate dimensions (number of rows) for bc_rounds

    into = interconversion target string; e.g. "row" "rc_i" "obj"
    all_ktype = flag to allow all kits; No filter for kit type="norm"

    Return list
    """
    # Make sure normal kit
    kit, _ = parse_kit(kit, chem=chem)
    if not kit:
        return []
    # Legit kit and chem combo
    df = kit_chem_dtab_subset(kit, chem, all_ktype=all_ktype)
    if (df is None) or (len(df) < 1):
        return []

    # If chem is 0, df will have multiple rows, but all kits are the same
    answer = df["sp_dims"].iloc[0]
    # Possibly change representation
    if into:
        # answer = plates.interconvert_dims(answer, into=into)
        pass
    return answer


def kit_chem_str(
    kit, chem, rep_kit_chem=True, plate_dims=True, bc_names=True, all_ktype=True
):
    """Get story describing kit chem params

    all_ktype = flag to allow all kits; No filter for kit type="norm"

    kit and chem must be a valid unique combination

    Return str
    """
    df = kit_chem_dtab_subset(kit, chem, all_ktype=all_ktype)
    if (df is None) or (len(df) < 1):
        return ""

    story = ""
    if rep_kit_chem:
        chem = parse_chemistry(chem, as_str=True)
        kit, _ = parse_kit(kit, chem=chem)
        story = f"Kit {kit}; Chemistry {chem}"

    # Plate dimensions (don't need chem; kit should be the same for all)
    if plate_dims:
        # Change format into (row, col) tuples
        p_dims = kit_chem_plate_dims(kit, into="rc_i")
        ppart = "Plate rows"
        pref = "; " if story else ""
        story += f"{pref}{ppart} {p_dims}"

    # Barcode names (need chemistry here)
    if bc_names and chem:
        df_dict = df.iloc[0].to_dict()
        pref = "; " if story else ""
        story += f"{pref}Barcodes {df_dict['bc1']}, {df_dict['bc2']}, {df_dict['bc3']}"

    return story


def kit_bc_set_list(kit, chem, as_tup=False, all_ktype=True):
    """Get list of barcode set names for kit and chemistry

    as_tup = flag to return list of [bcX, name] items vs names
    all_ktype = flag to allow all kits; No filter for kit type="norm"

    Return list of barcode names per round
    """
    df = kit_chem_dtab_subset(kit, chem, all_ktype=all_ktype)
    if (df is None) or (len(df) > 1):
        return []

    bc_list = []
    cols = [f"bc{r}" for r in "123"]
    bc_list = list(df.loc[df.index, cols].values.flatten())
    # Tuple as [bcX, name]? This form matches 'bc_round_set' param
    if as_tup:
        new_list = []
        for col, bc in zip(cols, bc_list):
            new_list.append([col, bc])
        bc_list = new_list
    return bc_list


def report_valid_kits(chem=None, only_normal=True, pad=True):
    """Report kit collection;

    If not given chemistry, report that too

    Returns nothing
    """
    # List of all kit names, possibly limited to chem and ktype
    all_ktype = False if only_normal else True
    kc_list = kit_chem_list(kit=0, chem=chem, all_ktype=all_ktype)

    # Cook up dict with chem list for each kit
    kc_dict = {}
    chem_set = set()
    for k, c in kc_list:
        chem_set.add(c)
        chem_str = f"v{c}"
        if k in kc_dict:
            kc_dict[k].append(chem_str)
        else:
            kc_dict[k] = [chem_str]

    if pad:
        print()
    print(
        f"There are {len(kc_dict)} installed kits across {len(chem_set)} chemistries:\n"
    )
    for kit, c_list in kc_dict.items():
        story = kit_chem_str(kit, chem, rep_kit_chem=False, bc_names=False)
        chemistry = ", ".join(c_list)
        print(f"    {kit:14s} {story:20s}   Chemistry: {chemistry}")
    if pad:
        print()


# ---------------------------------------------------------------------------
# 96 well plate label / index lists
#
# Limit number of plates supported (e.g. parsed)
PLATE96_MAX_PLATES = 4
PLATE96_MAX_ROWS = PLATE96_MAX_PLATES * 8
#
PLATE96_ROWS = list("ABCDEFGH")
for plate in range(1, PLATE96_MAX_PLATES):
    PLATE96_ROWS += [f"p{plate+1}.{r}" for r in list("ABCDEFGH")]
PLATE96_COLS = [str(i + 1) for i in range(12)]


def wells_for_96plate(n_rows=8, as_int=False, as_wind=False, as_row_col=False):
    """Get list of wells for 96 well plate(s); Preface with plate number if > 1

    n_rows = number of rows (e.g. different kits have diff row count)
            (number of cols always 12)
    as_int = flag to return int 1-based index
    as_wind = flag to return zero-padded index strings (e.g. "26", "07")
    as_row_col = flag to return (row, col) tuples; If int, 0-based coords, else str

    default well = string row+col, with plate number if rows > 8; e.g. "D5", "p2.A4"

    return list
    """
    wells = []
    wint = 0
    for row in range(n_rows):
        letter = PLATE96_ROWS[row % 8]
        plate = num_96plates_for_rows(row + 1)
        plate_str = f"p{plate}." if plate > 1 else ""
        for col in range(12):
            if as_row_col:
                if as_int:
                    wells.append((row, col))
                else:
                    wells.append((f"{plate_str}{letter}", str(col + 1)))
            elif as_int or as_wind:
                wint += 1
                wells.append(wint)
            else:
                wells.append(f"{plate_str}{letter}{col+1}")

    # If as wind, replace wint with formatted str
    if as_wind:
        wind_list = []
        for wint in wells:
            # Zero pad 2 or 3 places depending on max index width
            wind = f"{wint:03d}" if max(wells) > 99 else f"{wint:02d}"
            wind_list.append(wind)
        wells = wind_list

    return wells


def num_96plates_for_rows(n_rows):
    """Number of 96 well plates for given number of rows (Always 12 cols)

    1-8 rows = 1 plate, 9-16 rows = 2 plates, etc
    """
    n_plates = ((int(n_rows) - 1) // 8) + 1
    return n_plates


# ---------------------------------------------------------------------------
# Various well mapping dicts, structs for parsing; Create once as globals
#
well_list = wells_for_96plate(n_rows=PLATE96_MAX_ROWS)
wint_list = wells_for_96plate(n_rows=PLATE96_MAX_ROWS, as_int=True)
rc_int_list = wells_for_96plate(n_rows=PLATE96_MAX_ROWS, as_int=True, as_row_col=True)
#
# Mapping plate 0-base coords to well string; e.g. (1,3) or ('B', '4') <--> B4 or 16
PLATE96_RC_INT_TO_WELL = dict(zip(rc_int_list, well_list))
PLATE96_WELL_TO_RC_INT = dict(zip(well_list, rc_int_list))
PLATE96_WINT_TO_RC_INT = dict(zip(wint_list, rc_int_list))
PLATE96_WELL_TO_RC_STR = {}
PLATE96_WINT_TO_RC_STR = {}
for well, wint, tup in zip(well_list, wint_list, rc_int_list):
    row = PLATE96_ROWS[tup[0]]
    col = PLATE96_COLS[tup[1]]
    PLATE96_WELL_TO_RC_STR[well] = (row, col)
    PLATE96_WINT_TO_RC_STR[wint] = (row, col)

#
# Mapping plate 1-base int index to well string; e.g. 16 <--> B4
PLATE96_WINT_TO_WELL = dict(zip(wint_list, well_list))
PLATE96_WELL_TO_WINT = dict(zip(well_list, wint_list))
#
# Well lists as 1D and 2D arrays; For compound slicing; e.g. "A1:C4", "A1-B6"
PLATE96_1D_WELLS = well_list
PLATE96_2D_WELLS = np.array(well_list).reshape(PLATE96_MAX_ROWS, 12)
#
# Parsing regex
WELL96_REGEX = re.compile(r"^(?:[Pp](\d+)\.?)?([ABCDEFGHabcdefgh])([1-9]|1[012])$")
# Split multi-bc-round like "B1__p2.G3"
MRBC_SPLIT_REGEX = re.compile("_+")


# -------------------- Well specification parsing ---------------------------
#
def match_one_wspec_block(block):
    """Attempt to match one well specification block: <[plate]<row><col>>

    Split block into plate number, well letter, col number
    Reconstruct cannonical, case-insenstivie well spec and return that too
    For example:
        'a6' >--> ('A6', 1, 'A', 6)
        'p1.B4' >--> ('B4', 1, 'B', 4)          # Note 'p1.' is removed from plate 1
        'P2.C11' >--> ('p2.C11', 2, 'C', 11)

    Return status, tuple
    """
    ok = False
    plate = r_let = c_num = well = ""
    match = WELL96_REGEX.match(block)
    if match:
        ok = True
        # No plate specification defaults to 1
        plate = 1 if match[1] is None else int(match[1])
        # No prefix for plate
        p_str = f"p{plate}." if plate > 1 else ""
        r_let = match[2].upper()
        c_num = match[3]
        # Reconstruct well spec string
        well = f"{p_str}{r_let}{c_num}"

        # Well must be in allowed / defined wells list
        assert (
            well in PLATE96_1D_WELLS
        ), f"'{well}' is not in wells up to {PLATE96_MAX_PLATES} plates"

    return ok, (well, plate, r_let, c_num)


def match_two_wspec_block(block, sep):
    """Attempt to parse both sides of a compound well spec; e.g. "A1:C4", "A1-B6"

    No error handling; Expect to be in try / except block for failure

    Return status, s_well, e_well
    """
    parts = block.split(sep)
    assert len(parts) == 2, f"'{block}' does not split into 2 with '{sep}'"
    s_ok, s_mat = match_one_wspec_block(parts[0])
    assert s_ok, f"Part '{parts[0]}' of '{block}' does not specify a valid well"
    e_ok, e_mat = match_one_wspec_block(parts[1])
    assert e_ok, f"Part '{parts[1]}' of '{block}' does not specify a valid well"
    s_well = s_mat[0]
    e_well = e_mat[0]
    ok = s_ok and e_ok
    return ok, s_well, e_well


def parse_mround_plate96_wells(wspec):
    """Parse potentially multi-bc_round well specification into well indexes

    Wrapper for parse_96wells to handle multipe round specs: e.g. "R1wells__R2wells"

    Return parse status, list of wells per round, cannonically formated wspec
    Returns lists for wells even if there is just one round plate
    Story only has content if there are parsing issues

    Return tuple (status, list[str], list[list], story)
    """
    ok = False
    story = ""
    wlist_list = []
    canon_wspec_list = []
    wspec_list = split_mround_plate96_wspec(wspec)
    for r, r_wspec in enumerate(wspec_list):
        ok, wells, canon_wspec, story = parse_plate96_wells(r_wspec)
        if not ok:
            # If multi-round, add starting spec to story
            if len(wspec_list) > 1:
                story = f"{story}, bc-round {r+1} of {wspec}"
            break
        wlist_list.append(wells)
        canon_wspec_list.append(canon_wspec)

    # Cannonical name if all good; If bad, empty list
    if ok:
        canon_wspec = join_mround_plate96_wspec(canon_wspec_list)
    else:
        wlist_list = []

    return ok, wlist_list, canon_wspec, story


def parse_plate96_wells(wspec):
    """Parse well specification string for one bc round into well indexes

    wspec = well specification; e.g. 'A4,C5:D8' 'B4-B9', 'p2A1:D12', etc

    Returns list of cannonically named individual wells, cannonically formated wspec
    Story only has content if there are parsing issues

    well_list = list of list for each round; Like this:
        'A1:D1' >--> [['A1', 'B1', 'C1', 'D1']]
        'A1:D1__p2.C1-p2.C4' >--> [['A1', 'B1', 'C1', 'D1'], ['p2.C1', 'p2.C2', 'p2.C3', 'p2.C4']]

    Return tuple (status, well_list, canon_wspec, story)
    """
    ok = True
    story = canon_wspec = ""
    well_list = []

    # Try will fail on non-match / error cases
    try:
        cspec_list = []
        for block in wspec.split(","):
            ok = False
            # Block spec like "B6:D9"
            if ":" in block:
                ok, s_well, e_well = match_two_wspec_block(block, ":")
                if not ok:
                    break
                s_row, s_col = PLATE96_WELL_TO_RC_INT[s_well]
                e_row, e_col = PLATE96_WELL_TO_RC_INT[e_well]
                block_list = list(
                    PLATE96_2D_WELLS[s_row : e_row + 1, s_col : e_col + 1].flatten()
                )
                ok = bool(len(block_list))
                if ok:
                    well_list += block_list
                    cspec_list.append(f"{s_well}:{e_well}")
                else:
                    story = f"'{block}' doesn't define a valid block of wells"
                    raise ValueError(story)
            # Range spec like "B6-D9"
            elif "-" in block:
                ok, s_well, e_well = match_two_wspec_block(block, "-")
                if not ok:
                    break
                s_ind = PLATE96_1D_WELLS.index(s_well)
                e_ind = PLATE96_1D_WELLS.index(e_well)
                range_list = PLATE96_1D_WELLS[s_ind : e_ind + 1]
                ok = bool(len(range_list))
                if ok:
                    well_list += range_list
                    cspec_list.append(f"{s_well}-{e_well}")
                else:
                    story = f"'{block}' doesn't define a valid range of wells"
                    raise ValueError(story)
            # Single well
            else:
                ok, w_mat = match_one_wspec_block(block)
                if ok:
                    well_list.append(w_mat[0])
                    cspec_list.append(w_mat[0])
                else:
                    story = f"'{block}' does not specify a valid well"
                    raise ValueError(story)
        well_list = sort_wells([str(w) for w in np.unique(well_list)])
        canon_wspec = ",".join(cspec_list)
    except Exception as e:
        ok = False
        story = f"Problem well specification: '{block}' from '{wspec}'"
        story += f"\n{e}"
        pass

    return (ok, well_list, canon_wspec, story)


def split_mround_plate96_wspec(wspec):
    """Split well specification for multiple bc round well specs

    Return list
    """
    bcr_wspec = MRBC_SPLIT_REGEX.split(wspec)
    return bcr_wspec


def join_mround_plate96_wspec(wspec1, wspec2=""):
    """Joint multi-round well specs; ['A1:D2', 'A1:B12'] >--> 'A1:D2__A1:B12'

    Return str
    """
    if isinstance(wspec1, list):
        in_list = wspec1
    else:
        in_list = [wspec1]
        if wspec2:
            in_list.append(wspec2)

    return "__".join(in_list)


def sort_wells(wells):
    """Sort wells nicely (e.g. A1, A2, A10, p2.A1, p2.A10...)"""

    def sort_key(s):
        match = re.match(r"([A-Za-z]+)(\d+)", s)
        if match:
            prefix, number = match.groups()
            return (prefix, int(number))
        else:
            return (s, 0)  # fallback if pattern doesn't match

    return sorted(wells, key=sort_key)


# ------------------------------- misc utils ---------------------------------
#
def print_now(story, newline=True, file=sys.stdout):
    """Print plus fulsh buffer"""
    if newline:
        print(story, file=file)
    else:
        print(story, file=file, end="")
    file.flush()


# Matches float/int with optional sign and chars before / after
#   This part (?<![+-]) is not a capture; Instead prevents \D matching +-
#   From https://stackoverflow.com/questions/58841472/regex-for-digits-and-plus-minus-sign
NUM_REGEX = re.compile(r"\D*(?<![+-])([+-]?([0-9]*)(\.([0-9]+))?)\D*$")


#
def str_to_num(string, as_float=False, commas=True, regex=False):
    """Attempt to get number from string

    Return tuple (success, value)
    """
    # Optional clean up / extraction
    if isinstance(string, str):
        # Strip any commas?
        if commas:
            string = string.replace(",", "")
        # regex; Allows surrounding chars (e.g. 'abc-122.4x' >--> -122.4)
        if regex:
            mat = NUM_REGEX.match(string)
            if mat:
                string = mat[1]
    # Cast
    try:
        # Cast to float first regardless; then maybe int
        n = float(string)
        if not as_float:
            n = int(string)
        ok = True
    except Exception:
        ok = False
        n = string
    return ok, n


def parse_range_list(rlis, warn=True):
    """Parse range list; maybe [], [end], [start,end]

    first and last default zero; If given, set as int

    Return status,first,last
    """
    ok = True
    first = last = 0
    if rlis:
        if len(rlis) > 1:
            if (len(rlis) > 2) and warn:
                print(f"Extra range args ignored; {rlis}")
            ok, first = str_to_num(rlis[0])
            if ok:
                ok, last = str_to_num(rlis[1])
        else:
            ok, last = str_to_num(rlis[0])
    return ok, first, last


def range_story(r_ends):
    first = last = ""
    if r_ends:
        if len(r_ends) > 1:
            first, last = r_ends[:2]
        else:
            last = r_ends[0]
    if first and last:
        story = f"From {first} to {last} ({last - first})"
    elif last:
        story = f"To max {last}"
    else:
        story = "No restrictions"
    return story


def check_infile(fname, path=None, verb=True, toxic=False, dir_slash=True):
    """Check named input file(s) can be opened for read

    fname = filename or list of filenames; str or Path
    path = Path to prepend
    verb = Flag to report problem
    toxic = Flag to crash on problem
    dir_slash = flag to make sure fname ends '/' if is a dir

    Returns filename if readable; None if not
    """
    # Check if given empty str or None first
    if not fname:
        story = "Given empty filename to check"
        if toxic:
            raise IOError(story)
        if verb:
            print(story)
        return None

    # If given filename list, recur for each item
    if isinstance(fname, list):
        f_lis = []
        for f in fname:
            name = check_infile(
                f, path=path, verb=verb, toxic=toxic, dir_slash=dir_slash
            )
            if name:
                f_lis.append(name)
            else:
                f_lis = None
                break
        return f_lis

    r_fname = None

    # Path to prepend?
    if path:
        f_path = fname_full_path(path, dir_slash=True)
        if f_path:
            fname = f_path + fname
        else:
            story = f"Given path is bad: '{path}'"
            if toxic:
                raise IOError(story)
            if verb:
                print(story)
            return None

    # Expand any env vars; User for ~/ and vars for $home
    fname = os.path.expanduser(fname)
    fname = os.path.expandvars(fname)
    # Read access means input is good
    if os.access(fname, os.R_OK):
        r_fname = fname
        # If dir, expand to explicit path
        if os.path.isdir(r_fname):
            r_fname = fname_full_path(r_fname, dir_slash=dir_slash)
    else:
        story = f"Cannot read file: '{fname}'"
        if toxic:
            raise IOError(story)
        if verb:
            print(story)
    return r_fname


def fname_full_path(fname, dir_slash=True, strip=True, exists=True, toxic=False):
    """Expand filename to full path

    fname = filename or list of filenames
    dir_slash = flag to make sure fname ends '/' if is a dir
    strip = flag to strip surrounding whitespace
    exists = flag to only return existing path

    return filename or None
    """
    # Check if given empty str or None first
    if not fname:
        return None

    # If given filename list, recur for each item
    if isinstance(fname, list):
        f_lis = []
        for f in fname:
            name = fname_full_path(f, dir_slash=dir_slash, exists=exists)
            if name:
                f_lis.append(name)
            else:
                f_lis = None
                break
        return f_lis

    # Single file name string. Keep original name for error reporting
    o_fname = fname
    e_fname = None
    if strip:
        fname = fname.strip()
    # Expand any env vars; User for ~/ and vars for $home
    fname = os.path.expanduser(fname)
    fname = os.path.expandvars(fname)
    # This will strip out repeated, trailing slashes;
    #   '/path//to//x' >--> '/path/to/x'
    #   '/path//to//x/' >--> '/path/to/x'
    fname = os.path.normpath(fname)
    # Expand to absolute path if not already;
    #   './' >--> '/path/to/current_dir/'
    fname = os.path.abspath(fname)

    # Must be real file?
    if exists:
        if os.path.exists(fname):
            e_fname = fname
            # If dir, maybe need trailing slash
            if os.path.isdir(e_fname) and dir_slash:
                # Special case (e.g. normpath leaves '/' untouched)
                if e_fname[-1] != "/":
                    e_fname += "/"
        else:
            if toxic:
                story = f"Given file |{o_fname}| not found"
                raise IOError(story)
    else:
        e_fname = fname
        if dir_slash:
            e_fname = e_fname + "/"
    return e_fname


def open_possible_gz_file(fname, verb=True, toxic=False):
    """Attempt to open file for read that may or may not be gzip'd

    Return file handle
    """
    # Check returns cleaned name or nothing if file is bad; Crash if toxic
    c_fname = check_infile(fname, verb=verb, toxic=toxic)
    if not c_fname:
        story = f"Bad dataframe file ('.gz' or not); |{fname}|"
        if toxic:
            raise IOError(story)
        if verb:
            print(story)
        return None

    if c_fname.endswith(".gz"):
        return gzip.open(c_fname, "rt")
    else:
        return open(c_fname, "r")


