def get_perfect_bc_stats(comargs, bc_info):
    """Get sample of prefect barcode counts for correction. Also stats

    Sets counts and threshold into bc_info. Return dict with stats

    Return dict
    """
    # Only first fastq if multiple
    fname = comargs.fq2_list[0]

    first = comargs.bc_samp_first
    last = comargs.bc_samp_last
    num = last - first
    print_now(f"# Sampling {num} R2 reads ({first} to {last})")
    heads, seqs, quals = load_fastq_recs(fname, num, skip=first)
    if len(heads) < num:
        print(f"Problem with fastq sample; Got only {len(heads)} reads from {fname}")
        return None

    fq_df = pd.DataFrame({"head": heads, "seq": seqs, "qual": quals})
    bc_counts, count_threshold, stat_dict = get_perfect_bc_counts(fq_df, bc_info)

    # Save in bc_info
    bc_info["bc_counts"] = bc_counts
    bc_info["bc_count_thresh"] = count_threshold
    print_now(f"# Barcode counts {len(bc_counts)}, {count_threshold=}")

    return stat_dict


def load_fastq_recs(fpath, number, skip=0, head=True, seq=True, quality=True):
    """Read seqs from fastq / fastq.gz

    number = number to collect; If 0, collect all
    skip = number of initial records to skip
    head = flag to keep header lines too; Else empty list
    seq = flag to keep seq lines too; Else empty list
    quality = flag to keep quality lines too; Else empty list

    Return tuple of lists ([headers], [seqs], [qual])
    """
    INFILE = open_possible_gz_file(fpath)
    n = nkept = 0
    head_list = []
    seq_list = []
    qual_list = []
    while True:
        headline = INFILE.readline()
        seqline = INFILE.readline()
        # Don't use strand line
        _ = INFILE.readline()
        qualine = INFILE.readline()
        if not headline:
            break

        n += 1
        if n < skip:
            continue

        if head:
            # Strip leading @ from header
            head_list.append(headline.strip()[1:])
        if seq:
            seq_list.append(seqline.strip())
        if quality:
            qual_list.append(qualine.strip())

        nkept += 1
        if number and (nkept >= number):
            break

    INFILE.close()
    return (head_list, seq_list, qual_list)


def fq2_df_split_bc(df, amp_seq, fresh=False):
    """Add split barcode parts to fq2 (sampled) dataframe

    Return dataframe
    """
    bc_starts, bc_ends = get_amp_part_bounds(amp_seq)
    col_set = set(df.columns)
    seqs = df["seq"]
    quals = df["qual"]
    # Each barcode, starting from zero (0 = poly-N)
    n = 0
    for st, en in zip(bc_starts, bc_ends):
        if (en - st) > 0:
            bc_col = f"bc{n}"
            if fresh or (bc_col not in col_set):
                df[bc_col] = seqs.str.slice(bc_starts[n], bc_ends[n])

            qc_col = f"qc{n}"
            if fresh or (qc_col not in col_set):
                df[qc_col] = quals.str.slice(bc_starts[n], bc_ends[n])
        n += 1

    return df


def get_perfect_bc_counts(fq_df, bc_info, drop_valid_cols=True):
    """Evaluate sampled barcode sequences for perfect barcode counts

    fq_df = dataframe with R2 fastq seqs (will split out barcode seqs)
    bc_info = BCInfo struct
    drop_valid_cols = flag to delete added valid bc cols

    Return tuple (dict-with-count[perfect-bc-combo], threshold value, stats dict)
    """
    assert isinstance(fq_df, pd.DataFrame), f"Expected DataFrame got {type(fq_df)}"

    # Make sure barcode subseqs are split out
    fq_df = fq2_df_split_bc(fq_df, bc_info["amp_seq"])

    # Sets a bit faster for membership checking
    # For individual bc rounds, 1-based indexing
    bc1_seq_set = set(bc_info["bc_seqs"][1])
    bc2_seq_set = set(bc_info["bc_seqs"][2])
    bc3_seq_set = set(bc_info["bc_seqs"][3])

    # Boolean perfect match of subseq to seq sets
    fq_df["bc1_valid"] = fq_df["bc1"].apply(lambda s: s in bc1_seq_set)
    fq_df["bc2_valid"] = fq_df["bc2"].apply(lambda s: s in bc2_seq_set)
    fq_df["bc3_valid"] = fq_df["bc3"].apply(lambda s: s in bc3_seq_set)

    # Counts of (perfect) barcode combinations
    counts = (
        fq_df.query("bc1_valid & bc2_valid & bc3_valid")
        .groupby(["bc1", "bc2", "bc3"])
        .size()
        .sort_values(ascending=False)
    )

    # Empirical settings for calling valid barcodes
    reads_in_cell_frac = BC_READS_IN_CELL_FRAC
    calc = counts.iloc[
        abs(counts.cumsum() / counts.sum() - reads_in_cell_frac).values.argmin()
    ]
    count_threshold = max(5, calc)

    # Stats for perfect sequences
    n_all_valid = fq_df.query("bc1_valid & bc2_valid & bc3_valid").shape[0]
    stat_dict = {
        "bc1_perfrac": float(round(fq_df["bc1_valid"].sum() / len(fq_df), 3)),
        "bc2_perfrac": float(round(fq_df["bc2_valid"].sum() / len(fq_df), 3)),
        "bc3_perfrac": float(round(fq_df["bc3_valid"].sum() / len(fq_df), 3)),
        "bc123_perfrac": float(round(n_all_valid / len(fq_df), 3)),
    }

    # Clean up dataframe?
    if drop_valid_cols:
        drop_cols = "bc1_valid,bc2_valid,bc3_valid".split(",")
        fq_df.drop(drop_cols, axis=1, inplace=True)

    return counts.to_dict(), count_threshold, stat_dict


def guess_fastq_gz_read_count(fname, samp_num=800_000, skip=400_000, retry=True):
    """Estimate the total number of reads from sample of gzip'd fastq file

    With 200K sample, guesses seem to be < 2% error and pretty fast

    Return int, str
    """
    # Get the total size of the compressed file in bytes.
    total_size = os.path.getsize(fname)
    s_size_st = s_size_en = -1

    # Open the file in binary mode (not 'rt')
    to_end = False
    with gzip.open(fname, "rb") as INFILE:
        n = nkept = 0
        while True:
            # Don't need to keep anything, just count
            _ = INFILE.readline()
            _ = INFILE.readline()
            _ = INFILE.readline()
            _ = INFILE.readline()
            if not _:
                to_end = True
                break

            n += 1
            if n < skip:
                continue

            # Start file position in the compressed file.
            # Note: f.tell() returns the position in the decompressed stream, so use
            # f.fileobj.tell() to get position in the underlying compressed stream
            if nkept == 0:
                s_size_st = INFILE.fileobj.tell()

            nkept += 1
            if nkept >= samp_num:
                s_size_en = INFILE.fileobj.tell()
                break

    # Special case where counted everyhing; No math guess needed
    if nkept and to_end and (skip == 0):
        guess = nkept
        story = "Actual count"
    # Typical case where we have a sample of reads
    elif nkept:
        # Testing with small sample numbers suggests that there is maybe a cache with
        # the file(?), as you can get the same tell() result before/after 1K samples ...
        # so average compressed bytes per read can calculate to zero
        size_per_read = (s_size_en - s_size_st) / nkept
        # Estimate total number of reads in the file.
        if size_per_read > 0:
            guess = round(total_size / size_per_read)
            story = f"Guessed total {guess:,} reads from sample of {nkept:,}"
        else:
            guess = 0
            story = f"Failed to get read size info from {fname}, sample {samp_num=} too small?"
    else:
        # Retry from the start?
        if retry:
            guess, story = guess_fastq_gz_read_count(
                fname, samp_num=samp_num, skip=0, retry=False
            )
        else:
            guess = 0
            story = f"Failed to get any reads from {fname}, {skip=} {samp_num=}"

    return guess, story


