#
def jstring_to_bc_dict(jstrings=None):
    """Load all barcode data structs (from encoded string)

    Return dict with [name] = {'data': data, 'dict': dict}
    """
    # If not given string (normal in script), then process global string
    global global_bc_jstrings
    if not jstrings:
        jstrings = global_bc_jstrings

    # Split big string into lines to process
    # lines = jstrings.split("\n")
    # print(f"Total {len(lines)} lines in string with {len(jstrings)} char")

    # Collect data(frames) and dicts for each barcode
    bc_data = {}
    bc_dict = {}
    # Init name, data lines and data type
    name = dlines = dtype = ""
    # Split string by line to process
    for line in jstrings.split("\n"):
        if line.startswith(">bc_d"):
            # print(line)
            # Prior collected data
            if dlines:
                # String to object (dict)
                obj = json.loads(zlib.decompress(base64.b64decode(dlines)))
                # Seq data saved as dict but should be dataframe
                if dtype == "data":
                    obj = pd.DataFrame(obj)
                # Save to dict
                save_dict = bc_data if dtype == "data" else bc_dict
                save_dict[name] = obj
                # Next encoded obj
                dlines = ""
            # New name and type; Header like:
            #   >bc_data n192_v4 from bc_data_n192_v4.csv
            dtype = "dict" if "bc_dict" in line else "data"
            name = line.split()[1]
        else:
            dlines += line.strip()
    # Last one
    if dlines:
        # String to object (dict)
        obj = json.loads(zlib.decompress(base64.b64decode(dlines)))
        # Seq data saved as dict but should be dataframe
        if dtype == "data":
            obj = pd.DataFrame(obj)
        # Save to dict
        save_dict = bc_data if dtype == "data" else bc_dict
        save_dict[name] = obj

    # Combined data and dict per barcode set
    new_dict = {}
    for k in bc_data.keys():
        new_key = k.replace("bc_data_", "")
        new_dict[new_key] = {"data": bc_data[k], "dict": bc_dict[k]}
    return new_dict


# To split up amplicon template
DNA_BASES = set(list("ACGT"))


#
def get_amp_part_bounds(seq):
    """Get start and end coords (for slice) for non-base parts in seq

    Assumes amplicon like below, with BC as digit, (optional) polyN as N

    Result lists are indexed [0]=N; [1]=round1; [2]=round2; [3]=round3

    Return arrays of start and end coords (for string slicing)
    """
    non_dna = set(seq.upper()) - DNA_BASES
    num_parts = len(non_dna)
    # If no N given, bump size
    if "N" not in non_dna:
        num_parts += 1
    part_ends = [-1] * num_parts
    part_starts = [-1] * num_parts
    # Scan each char; Annotate non-base parts
    prev_pi = -1
    i = 0
    while i < len(seq):
        pi = bc_amp_part_index(seq[i])
        # Change of part
        if pi != prev_pi:
            if pi >= 0:
                part_starts[pi] = i
            if prev_pi >= 0:
                part_ends[prev_pi] = i
        prev_pi = pi
        i += 1

    # Last end coord
    if part_ends[prev_pi] < 0:
        part_ends[prev_pi] = i
    return part_starts, part_ends


def bc_amp_part_index(b):
    """Part index for given character

    If normal DNA base, -1
    If 'N' then = 0 for polyN
    If int, then int N for barcode-N
    """
    if b in DNA_BASES:
        index = -1
    else:
        if b == "N":
            index = 0
        else:
            index = int(b)
    return index


def get_barcode_info(comargs, all_bc_dict):
    """Get barcode data for given kit

    all_bc_dict has data(frame) and (edit)dict for all available barcode sets
    comargs includes kit info

    Return bc_info dict with lists of bc data
    """
    bc_info = {}
    # Barcode sequences and error-correct edit-dist dicts encoded as strings
    # These are global variables, so can get via name

    # Get (1-based) list of barcode set names based on kit
    bc_list = kit_bc_set_list(comargs.kit, comargs.chemistry)

    # Init lists with nothing (i.e. no round 0, rounds 1-3 have stuff)
    bc_seq_dfs = [None]
    bc_seqs = [None]
    bc_dicts = [None]
    bc_seq_to_bci = [None]
    bc_seq_to_well = [None]
    num_wells = [0]

    for i, bc in enumerate(bc_list):
        # First element has nothing
        # if i == 0:
        #    continue

        # Edit-dist dict
        # Need to make sure edit dist keys are int (not str, as get from json decode)
        new_dict = {}
        for k, v in all_bc_dict[bc]["dict"].items():
            new_dict[int(k)] = v
        bc_dicts.append(new_dict)

        # Seq data dataframe; Add plate and pwell cols
        bc_df = all_bc_dict[bc]["data"]
        bc_df = bc_df_add_plate_well(bc_df)

        # Save dataframe but also sequences as list and well counts
        bc_seq_dfs.append(bc_df)
        bc_seqs.append(list(bc_df["sequence"].values))
        num_wells.append(len(bc_df["well"].unique()))

        map_dict = get_bc_data_dicts(bc_df)
        bc_seq_to_bci.append(map_dict["bc_seq_to_bci"])
        bc_seq_to_well.append(map_dict["bc_seq_to_well"])

    # Pack everything
    bc_info["bc_seq_dfs"] = bc_seq_dfs
    bc_info["bc_seqs"] = bc_seqs
    bc_info["num_wells"] = num_wells
    bc_info["bc_seq_to_bci"] = bc_seq_to_bci
    bc_info["bc_seq_to_well"] = bc_seq_to_well
    bc_info["bc_dicts"] = bc_dicts

    # Amplicon info; Seq and start,end for each round (zero = polyN)
    bc_info["amp_seq"] = comargs.amp_seq
    bc_starts, bc_ends = get_amp_part_bounds(comargs.amp_seq)
    bc_info["bc_starts"] = bc_starts
    bc_info["bc_ends"] = bc_ends

    print(f"# Set barcodes for chemistry {comargs.chemistry}, kit {comargs.kit}")
    print(f"# BC rounds: {bc_list}")

    return bc_info


def get_bc_data_dicts(df):
    """Get field-to-field mapping dicts for bc dataframes

    Return dict of dicts
    """
    # Sequence keys
    bc_seq_to_bci = dict(zip(df["sequence"].values, df.index.values))
    bc_seq_to_well = dict(zip(df["sequence"].values, df["pwell"].values))

    new_dict = {
        "bc_seq_to_bci": bc_seq_to_bci,
        "bc_seq_to_well": bc_seq_to_well,
    }
    return new_dict


def bc_df_add_plate_well(df):
    """Add a plate-well column to handle multi-plate well address"""
    if "plate" in df.columns:
        df["plate"] = df["plate"].astype(int)
    else:
        df["plate"] = 1

    # Plate wells with prefix 'pN.' only added for plates > N=1
    df["pwell"] = np.where(
        df["plate"] > 1, "p" + df["plate"].astype(str) + "." + df["well"], df["well"]
    )
    return df


def correct_barcodes(bc1, bc2, bc3, counts, count_thresh, bc_dicts, max_d):
    """Correct barcode sequences using pre-calculated values

    bc_dicts = list of all per-bc_round dicts; 0-based index

    Return barcodes, edit distance max, edit distance sum
    """
    bc1_matches, edit_dist1, found1 = get_min_edit_dists(bc1, bc_dicts[1], max_d)
    bc2_matches, edit_dist2, found2 = get_min_edit_dists(bc2, bc_dicts[2], max_d)
    bc3_matches, edit_dist3, found3 = get_min_edit_dists(bc3, bc_dicts[3], max_d)
    # Valid if all found
    if found1 and found2 and found3:
        ed_max = max(edit_dist1, edit_dist2, edit_dist3)
        ed_sum = edit_dist1 + edit_dist2 + edit_dist3
    else:
        return "", "", "", -1, -1

    bc1_fixed = bc2_fixed = bc3_fixed = ""
    # Perfect match == done
    if 0 == edit_dist1 == edit_dist2 == edit_dist3:
        bc1_fixed = bc1_matches[0]
        bc2_fixed = bc2_matches[0]
        bc3_fixed = bc3_matches[0]
    # Look for single over-threshold combination
    else:
        matches = 0
        for bc1_m in bc1_matches:
            for bc2_m in bc2_matches:
                for bc3_m in bc3_matches:
                    try:
                        cur_counts = counts[(bc1_m, bc2_m, bc3_m)]
                    except Exception:
                        cur_counts = 0
                    if cur_counts > count_thresh:
                        bc1_fixed = bc1_m
                        bc2_fixed = bc2_m
                        bc3_fixed = bc3_m
                        matches += 1
                        # More than one possibility == don't use
                        if matches > 1:
                            bc1_fixed = bc2_fixed = bc3_fixed = ""
                            break

    return bc1_fixed, bc2_fixed, bc3_fixed, ed_max, ed_sum


def get_min_edit_dists(bc, edit_dict, max_d=DEF_BC_EDIT_DIST):
    """Returns a list of nearest edit dist seqs
    Input 8nt barcode, edit_dist_dictionary
    Output <list of nearest edit distance seqs>, <edit dist>
    """
    bc_matches = edit_dict[0].get(bc, [])
    edit_dist = 0
    found = bool(bc_matches)
    while (not found) and (edit_dist < max_d):
        edit_dist += 1
        bc_matches = edit_dict[edit_dist].get(bc, [])
        if bc_matches:
            found = True
            break
        if edit_dist >= max_d:
            break
    return bc_matches, edit_dist, found


